mapper.select:
SELECT 
FROM EDU_TRAIN_AGREEMENT A
WHERE A.ACTIVITY = '1'
  AND A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND A.AGREE_NO = #{agreeNo, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_TRAIN_AGREEMENT
   SET ACTIVITY = '0'
 WHERE AGREE_NO = #{agreeNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
